module vdu_v2_0_3_lc_registers
#(
parameter NUM_DECODER_INSTANCES = 1
)

(
input  wire                                     s_axi_lite_aclk,
input wire                                      m_axi_mcu_aclk,
input wire                                      m_axi_dec_aclk,
input  wire                                     pl_lc_raw_rst_n,

//Read Address
input  wire  [22:0]                             cb_lc_araddr_axi_lite_apb,
input  wire  [2:0]                              cb_lc_arprot_axi_lite_apb,
input  wire                                     cb_lc_arvalid_axi_lite_apb,
output  wire                                    lc_cb_arready_axi_lite_apb,

//Write Address
input  wire  [22:0]                             cb_lc_awaddr_axi_lite_apb,
input  wire  [2:0]                              cb_lc_awprot_axi_lite_apb,
input  wire                                     cb_lc_awvalid_axi_lite_apb,
output wire                                     lc_cb_awready_axi_lite_apb,

//Read data
output  wire  [31:0]                            lc_cb_rdata_axi_lite_apb,
output  wire  [1:0]                             lc_cb_rresp_axi_lite_apb,
output  wire                                    lc_cb_rvalid_axi_lite_apb,
input  wire                                     cb_lc_rready_axi_lite_apb,

//Write data-bus
input  wire  [31:0]                             cb_lc_wdata_axi_lite_apb,
input  wire  [3:0]                              cb_lc_wstrb_axi_lite_apb,
input  wire                                     cb_lc_wvalid_axi_lite_apb,
output wire                                     lc_cb_wready_axi_lite_apb,

//write-Resp Channel
output wire  [1:0]                              lc_cb_bresp_axi_lite_apb,
output wire                                     lc_cb_bvalid_axi_lite_apb,
input wire                                      cb_lc_bready_axi_lite_apb,

output wire [(NUM_DECODER_INSTANCES-1):0]       vdu_resetn_combined,
input wire  [(NUM_DECODER_INSTANCES-1):0]       locked,
input  wire [(NUM_DECODER_INSTANCES-1):0]       int_vdu_host_interrupt,
output wire                                     vdu_host_interrupt_combined,
output wire [3:0]                               secure_control, 
output wire [9:0]                               smid_vdu0_dec0,
output wire [9:0]                               smid_vdu0_dec1,
output wire [9:0]                               smid_vdu0_mcu,
output wire [9:0]                               smid_vdu1_dec0,
output wire [9:0]                               smid_vdu1_dec1,
output wire [9:0]                               smid_vdu1_mcu,
output wire [9:0]                               smid_vdu2_dec0,
output wire [9:0]                               smid_vdu2_dec1,
output wire [9:0]                               smid_vdu2_mcu,
output wire [9:0]                               smid_vdu3_dec0,
output wire [9:0]                               smid_vdu3_dec1,
output wire [9:0]                               smid_vdu3_mcu

);


localparam
    ADDR_NUM_DEC_INSTANCES        = 7'h50,   //READ_ONLY  GUI variable
    ADDR_VERSION_CONTROL          = 7'h0,    //READ_ONLY  3:0 - Minor revision, 7:4 - Major revision
    ADDR_LC_LOCK_REGISTER         = 7'h4,    //WRITE_ONLY  31:0 - 0x7766DF77- unlock VDU register space , 0x0- lock VDU register space
    ADDR_CONTROL_REGISTER         = 7'h8,    //RW         0- soft resert to VDU0, 1-soft reset to VDU1
    ADDR_SECURE_CONTROL           = 7'hc,    //RW         0-Secure/non-secure configuration for VDU0, 1- Secure/non-secure configuration for VDU1
    ADDR_SMID_CONTROL_REGISTER_0  = 7'h10,   //RW         9:0- SMID for VDU0, DEC0
    ADDR_SMID_CONTROL_REGISTER_1  = 7'h14,   //RW         9:0- SMID for VDU0, DEC1
    ADDR_SMID_CONTROL_REGISTER_2  = 7'h18,   //RW         9:0- SMID for VDU0, MCU
    ADDR_SMID_CONTROL_REGISTER_3  = 7'h1c,   //RW         9:0- SMID for VDU1, DEC0
    ADDR_SMID_CONTROL_REGISTER_4  = 7'h20,   //RW         9:0- SMID for VDU1, DEC1
    ADDR_SMID_CONTROL_REGISTER_5  = 7'h24,   //RW         9:0- SMID for VDU1, MCU
    ADDR_SMID_CONTROL_REGISTER_6  = 7'h28,   //RW         9:0- SMID for VDU2, DEC0
    ADDR_SMID_CONTROL_REGISTER_7  = 7'h2c,   //RW         9:0- SMID for VDU2, DEC1
    ADDR_SMID_CONTROL_REGISTER_8  = 7'h30,   //RW         9:0- SMID for VDU2, MCU
    ADDR_SMID_CONTROL_REGISTER_9  = 7'h34,   //RW         9:0- SMID for VDU3, DEC0
    ADDR_SMID_CONTROL_REGISTER_10 = 7'h38,   //RW         9:0- SMID for VDU3, DEC1
    ADDR_SMID_CONTROL_REGISTER_11 = 7'h3c,   //RW         9:0- SMID for VDU3, MCU
    ADDR_INTERRUPT_CLEAR          = 7'h54,


    WRIDLE                       = 2'd0,
    WRDATA                       = 2'd1,
    WRRESP                       = 2'd2,
    WRRESET                      = 2'd3,
    RDIDLE                       = 2'd0,
    RDDATA                       = 2'd1,
    RDRESET                      = 2'd2,
    ADDR_BITS                    = 7;    // ?

//------------------------Local signal-------------------
    reg  [1:0]                    wstate;
    reg  [1:0]                    wnext;
    reg  [ADDR_BITS-1:0]          waddr;
    wire [31:0]                   wmask;
    wire                          aw_hs;
    wire                          w_hs;
    wire                          w_hs_unlocked;
    reg  [1:0]                    rstate;
    reg  [1:0]                    rnext;
    reg  [9:0]                    rdata;
    wire                          ar_hs;
    wire [ADDR_BITS-1:0]          raddr;
    // internal registers
    wire [2:0]                    int_NUM_DEC_INSTANCES;
    wire [7:0]                    int_VERSION_CONTROL;
    reg  [31:0]                   int_LC_LOCK_REGISTER; 
    reg  [3:0]                    int_CONTROL_REGISTER;
    wire  [3:0]                    int_CONTROL_REGISTER_dummy;
    reg  [3:0]                    int_SECURE_CONTROL;
    reg  [9:0]                    int_SMID_CONTROL_REGISTER_0;
    reg  [9:0]                    int_SMID_CONTROL_REGISTER_1;
    reg  [9:0]                    int_SMID_CONTROL_REGISTER_2;
    reg  [9:0]                    int_SMID_CONTROL_REGISTER_3;
    reg  [9:0]                    int_SMID_CONTROL_REGISTER_4;
    reg  [9:0]                    int_SMID_CONTROL_REGISTER_5;
    reg  [9:0]                    int_SMID_CONTROL_REGISTER_6;
    reg  [9:0]                    int_SMID_CONTROL_REGISTER_7;
    reg  [9:0]                    int_SMID_CONTROL_REGISTER_8;
    reg  [9:0]                    int_SMID_CONTROL_REGISTER_9;
    reg  [9:0]                    int_SMID_CONTROL_REGISTER_10;
    reg  [9:0]                    int_SMID_CONTROL_REGISTER_11;
//    reg  [3:0]                    int_INTERRUPT_CLEAR;
    
    reg  [(NUM_DECODER_INSTANCES-1):0]                    int_vdu_host_interrupt_reg ;
    reg  [(NUM_DECODER_INSTANCES-1):0]                    int_vdu_host_interrupt1;
    reg  [(NUM_DECODER_INSTANCES-1):0]                    int_vdu_host_interrupt2;
    reg  [2:0] cnt_rst [(NUM_DECODER_INSTANCES-1):0] ;

    wire                          device_unlocked ;
    wire                          Instance_1;
    wire                          Instance_2;
    wire                          Instance_3;
    wire                          Instance_4;





//------------------------AXI write fsm------------------
assign lc_cb_awready_axi_lite_apb = (wstate == WRIDLE);
assign lc_cb_wready_axi_lite_apb  = (wstate == WRDATA);
assign lc_cb_bresp_axi_lite_apb   = 2'b00;  // OKAY
assign lc_cb_bvalid_axi_lite_apb  = (wstate == WRRESP);
assign wmask   = { {8{cb_lc_wstrb_axi_lite_apb[3]}}, {8{cb_lc_wstrb_axi_lite_apb[2]}}, {8{cb_lc_wstrb_axi_lite_apb[1]}}, {8{cb_lc_wstrb_axi_lite_apb[0]}} };
assign aw_hs   = cb_lc_awvalid_axi_lite_apb & lc_cb_awready_axi_lite_apb;
assign w_hs    = (device_unlocked == 1'b1) ? (cb_lc_wvalid_axi_lite_apb & lc_cb_wready_axi_lite_apb) : 1'b0;
assign w_hs_unlocked    = cb_lc_wvalid_axi_lite_apb & lc_cb_wready_axi_lite_apb;

// wstate
always @(posedge s_axi_lite_aclk) begin
    if (~pl_lc_raw_rst_n)
        wstate <= WRRESET;
    else
        wstate <= wnext;
end

// wnext
always @(*) begin
    case (wstate)
        WRIDLE:
            if (cb_lc_awvalid_axi_lite_apb)
                wnext = WRDATA;
            else
                wnext = WRIDLE;
        WRDATA:
            if (cb_lc_wvalid_axi_lite_apb)
                wnext = WRRESP;
            else
                wnext = WRDATA;
        WRRESP:
            if (cb_lc_bready_axi_lite_apb)
                wnext = WRIDLE;
            else
                wnext = WRRESP;
        default:
            wnext = WRIDLE;
    endcase
end

// waddr
always @(posedge s_axi_lite_aclk) begin
        if (aw_hs)
            waddr <= cb_lc_awaddr_axi_lite_apb[ADDR_BITS-1:0];
end

//------------------------AXI read fsm-------------------
assign lc_cb_arready_axi_lite_apb = (rstate == RDIDLE);
assign lc_cb_rdata_axi_lite_apb   = rdata;
assign lc_cb_rresp_axi_lite_apb   = 2'b00;  // OKAY
assign lc_cb_rvalid_axi_lite_apb  = (rstate == RDDATA);
assign ar_hs   = cb_lc_arvalid_axi_lite_apb & lc_cb_arready_axi_lite_apb;
assign raddr   = cb_lc_araddr_axi_lite_apb[ADDR_BITS-1:0];

// rstate
always @(posedge s_axi_lite_aclk) begin
    if (~pl_lc_raw_rst_n)
        rstate <= RDRESET;
    else
        rstate <= rnext;
end

// rnext
always @(*) begin
    case (rstate)
        RDIDLE:
            if (cb_lc_arvalid_axi_lite_apb)
                rnext = RDDATA;
            else
                rnext = RDIDLE;
        RDDATA:
            if (cb_lc_rready_axi_lite_apb & lc_cb_rvalid_axi_lite_apb)
                rnext = RDIDLE;
            else
                rnext = RDDATA;
        default:
            rnext = RDIDLE;
    endcase
end

// rdata
always @(posedge s_axi_lite_aclk) begin
        if (ar_hs) begin
            rdata <= {10{1'b0}};
            if(device_unlocked)
	       case (raddr)
                    ADDR_NUM_DEC_INSTANCES:        rdata <= int_NUM_DEC_INSTANCES;
                    ADDR_VERSION_CONTROL:          rdata <= int_VERSION_CONTROL;
                    ADDR_CONTROL_REGISTER:         rdata <= int_CONTROL_REGISTER;
                    ADDR_SECURE_CONTROL:           rdata <= int_SECURE_CONTROL;
                    ADDR_SMID_CONTROL_REGISTER_0:  rdata <= int_SMID_CONTROL_REGISTER_0;
                    ADDR_SMID_CONTROL_REGISTER_1:  rdata <= int_SMID_CONTROL_REGISTER_1;
                    ADDR_SMID_CONTROL_REGISTER_2:  rdata <= int_SMID_CONTROL_REGISTER_2;
                    ADDR_SMID_CONTROL_REGISTER_3:  rdata <= int_SMID_CONTROL_REGISTER_3;
                    ADDR_SMID_CONTROL_REGISTER_4:  rdata <= int_SMID_CONTROL_REGISTER_4;
                    ADDR_SMID_CONTROL_REGISTER_5:  rdata <= int_SMID_CONTROL_REGISTER_5;
                    ADDR_SMID_CONTROL_REGISTER_6:  rdata <= int_SMID_CONTROL_REGISTER_6;
                    ADDR_SMID_CONTROL_REGISTER_7:  rdata <= int_SMID_CONTROL_REGISTER_7;
                    ADDR_SMID_CONTROL_REGISTER_8:  rdata <= int_SMID_CONTROL_REGISTER_8;
                    ADDR_SMID_CONTROL_REGISTER_9:  rdata <= int_SMID_CONTROL_REGISTER_9;
                    ADDR_SMID_CONTROL_REGISTER_10: rdata <= int_SMID_CONTROL_REGISTER_10;
                    ADDR_SMID_CONTROL_REGISTER_11: rdata <= int_SMID_CONTROL_REGISTER_11;
//                    ADDR_INTERRUPT_CLEAR:          rdata <= int_INTERRUPT_CLEAR;
                endcase
	    else
            rdata <= {10{1'b0}};
        end
end


assign int_NUM_DEC_INSTANCES = NUM_DECODER_INSTANCES;  //GUI variable
assign int_VERSION_CONTROL = 'h5;              //Version control register


//LogiCORE Lock register
always @(posedge s_axi_lite_aclk) begin  
    if (~pl_lc_raw_rst_n)
        int_LC_LOCK_REGISTER <= 0;
    else begin
        if (w_hs_unlocked && waddr == ADDR_LC_LOCK_REGISTER)
            int_LC_LOCK_REGISTER <= (cb_lc_wdata_axi_lite_apb[31:0] & wmask) | (int_LC_LOCK_REGISTER & ~wmask);
    end
end

//assign device_unlocked = (int_LC_LOCK_REGISTER == 'h7766DF77) ? 1'b1 : 1'b0;
//assign device_unlocked = (int_LC_LOCK_REGISTER == 'h7766DF77) ? 1'b1 : (int_LC_LOCK_REGISTER == 'h0) ? 1'b0 : device_unlocked;
assign device_unlocked = (int_LC_LOCK_REGISTER == 'h7766DF77);

//assign int_CONTROL_REGISTER_dummy = (w_hs && waddr == ADDR_CONTROL_REGISTER) ? cb_lc_wdata_axi_lite_apb[3:0] : int_CONTROL_REGISTER;
//assign Instance_1 = (w_hs && waddr == ADDR_CONTROL_REGISTER) ? cb_lc_wdata_axi_lite_apb[0] : 0;
//assign Instance_2 = (w_hs && waddr == ADDR_CONTROL_REGISTER) ? cb_lc_wdata_axi_lite_apb[1] : 0;
//assign Instance_3 = (w_hs && waddr == ADDR_CONTROL_REGISTER) ? cb_lc_wdata_axi_lite_apb[2] : 0;
//assign Instance_4 = (w_hs && waddr == ADDR_CONTROL_REGISTER) ? cb_lc_wdata_axi_lite_apb[3] : 0;

//Soft Reset

genvar i;
generate
for (i=0; i<NUM_DECODER_INSTANCES; i=i+1)
begin: soft_gen_inst

    always @(posedge s_axi_lite_aclk) begin  //RW  0- soft resert to VDU0, 1-soft reset to VDU1, 2- soft resert to VDU2, 3-soft reset to VDU3
        if (~pl_lc_raw_rst_n)
          int_CONTROL_REGISTER[i] <= 0;
        else begin
           if (w_hs && waddr == ADDR_CONTROL_REGISTER) 
                //  int_CONTROL_REGISTER[0] <= Instance_1; 
               //   int_CONTROL_REGISTER[1] <= Instance_2;
                ////  int_CONTROL_REGISTER[2] <= Instance_3;
               //   int_CONTROL_REGISTER[3] <= Instance_4; end
               int_CONTROL_REGISTER[i] <= cb_lc_wdata_axi_lite_apb[i];
           // int_CONTROL_REGISTER <= cb_lc_wdata_axi_lite_apb[3:0] ;  //Assuming user writes 1 to reset and 0 to release.
       	   else
               if ((int_CONTROL_REGISTER[i] == 1'b1) & (cnt_rst[i] =={3{1'b1}}))
                   int_CONTROL_REGISTER[i] <= 1'b0;
               	end
    end

   always@(posedge s_axi_lite_aclk) begin
        if (~pl_lc_raw_rst_n)
             cnt_rst[i]<=3'd0;
        else if (int_CONTROL_REGISTER[i]==1'b1)
             cnt_rst[i]<=cnt_rst[i] + 1'b1;
        else
             cnt_rst[i]<=3'd0;
    end

      
    assign vdu_resetn_combined[i] = (pl_lc_raw_rst_n & (~int_CONTROL_REGISTER[i]) & locked[i]); 
end
endgenerate
//End of Soft Reset

//Secure/non-secure configuration
always @(posedge s_axi_lite_aclk) begin
    if (~pl_lc_raw_rst_n)
        int_SECURE_CONTROL <= 0;
    else begin
        if (w_hs && waddr == ADDR_SECURE_CONTROL)
            int_SECURE_CONTROL <= cb_lc_wdata_axi_lite_apb[3:0];
    end
end

//assign secure_control      = int_SECURE_CONTROL;

xpm_cdc_array_single #(
   .DEST_SYNC_FF(2),   // DECIMAL; range: 2-10
   .INIT_SYNC_FF(0),   // DECIMAL; 0=disable simulation init values, 1=enable simulation init values
   .SIM_ASSERT_CHK(0), // DECIMAL; 0=disable simulation messages, 1=enable simulation messages
   .SRC_INPUT_REG(1),  // DECIMAL; 0=do not register input, 1=register input
   .WIDTH(4)           // DECIMAL; range: 1-1024
)
xpm_cdc_array_single_inst_secure (
   .dest_out(secure_control), // WIDTH-bit output: src_in synchronized to the destination clock domain. This
                        // output is registered.

   .dest_clk(m_axi_mcu_aclk), // 1-bit input: Clock signal for the destination clock domain.
   .src_clk(s_axi_lite_aclk),   // 1-bit input: optional; required when SRC_INPUT_REG = 1
   .src_in(int_SECURE_CONTROL)      // WIDTH-bit input: Input single-bit array to be synchronized to destination clock
                        // domain. It is assumed that each bit of the array is unrelated to the others. This
                        // is reflected in the constraints applied to this macro. To transfer a binary value
                        // losslessly across the two clock domains, use the XPM_CDC_GRAY macro instead.

);
xpm_cdc_array_single #(
   .DEST_SYNC_FF(2),   // DECIMAL; range: 2-10
   .INIT_SYNC_FF(0),   // DECIMAL; 0=disable simulation init values, 1=enable simulation init values
   .SIM_ASSERT_CHK(0), // DECIMAL; 0=disable simulation messages, 1=enable simulation messages
   .SRC_INPUT_REG(1),  // DECIMAL; 0=do not register input, 1=register input
   .WIDTH(10)           // DECIMAL; range: 1-1024
)
xpm_cdc_array_single_inst_0 (
   .dest_out(smid_vdu0_dec0), // WIDTH-bit output: src_in synchronized to the destination clock domain. This
                        // output is registered.

   .dest_clk(m_axi_dec_aclk), // 1-bit input: Clock signal for the destination clock domain.
   .src_clk(s_axi_lite_aclk),   // 1-bit input: optional; required when SRC_INPUT_REG = 1
   .src_in(int_SMID_CONTROL_REGISTER_0)      // WIDTH-bit input: Input single-bit array to be synchronized to destination clock
                        // domain. It is assumed that each bit of the array is unrelated to the others. This
                        // is reflected in the constraints applied to this macro. To transfer a binary value
                        // losslessly across the two clock domains, use the XPM_CDC_GRAY macro instead.

);


xpm_cdc_array_single #(
   .DEST_SYNC_FF(2),   // DECIMAL; range: 2-10
   .INIT_SYNC_FF(0),   // DECIMAL; 0=disable simulation init values, 1=enable simulation init values
   .SIM_ASSERT_CHK(0), // DECIMAL; 0=disable simulation messages, 1=enable simulation messages
   .SRC_INPUT_REG(1),  // DECIMAL; 0=do not register input, 1=register input
   .WIDTH(10)           // DECIMAL; range: 1-1024
)
xpm_cdc_array_single_inst_1 (
   .dest_out(smid_vdu0_dec1), // WIDTH-bit output: src_in synchronized to the destination clock domain. This
                        // output is registered.

   .dest_clk(m_axi_dec_aclk), // 1-bit input: Clock signal for the destination clock domain.
   .src_clk(s_axi_lite_aclk),   // 1-bit input: optional; required when SRC_INPUT_REG = 1
   .src_in(int_SMID_CONTROL_REGISTER_1)      // WIDTH-bit input: Input single-bit array to be synchronized to destination clock
                        // domain. It is assumed that each bit of the array is unrelated to the others. This
                        // is reflected in the constraints applied to this macro. To transfer a binary value
                        // losslessly across the two clock domains, use the XPM_CDC_GRAY macro instead.

);

// End of xpm_cdc_array_single_inst instantiation


xpm_cdc_array_single #(
   .DEST_SYNC_FF(2),   // DECIMAL; range: 2-10
   .INIT_SYNC_FF(0),   // DECIMAL; 0=disable simulation init values, 1=enable simulation init values
   .SIM_ASSERT_CHK(0), // DECIMAL; 0=disable simulation messages, 1=enable simulation messages
   .SRC_INPUT_REG(1),  // DECIMAL; 0=do not register input, 1=register input
   .WIDTH(10)           // DECIMAL; range: 1-1024
)
xpm_cdc_array_single_inst_2 (
   .dest_out(smid_vdu0_mcu), // WIDTH-bit output: src_in synchronized to the destination clock domain. This
                        // output is registered.

   .dest_clk(m_axi_mcu_aclk), // 1-bit input: Clock signal for the destination clock domain.
   .src_clk(s_axi_lite_aclk),   // 1-bit input: optional; required when SRC_INPUT_REG = 1
   .src_in(int_SMID_CONTROL_REGISTER_2)      // WIDTH-bit input: Input single-bit array to be synchronized to destination clock
                        // domain. It is assumed that each bit of the array is unrelated to the others. This
                        // is reflected in the constraints applied to this macro. To transfer a binary value
                        // losslessly across the two clock domains, use the XPM_CDC_GRAY macro instead.

);

xpm_cdc_array_single #(
   .DEST_SYNC_FF(2),   // DECIMAL; range: 2-10
   .INIT_SYNC_FF(0),   // DECIMAL; 0=disable simulation init values, 1=enable simulation init values
   .SIM_ASSERT_CHK(0), // DECIMAL; 0=disable simulation messages, 1=enable simulation messages
   .SRC_INPUT_REG(1),  // DECIMAL; 0=do not register input, 1=register input
   .WIDTH(10)           // DECIMAL; range: 1-1024
)
xpm_cdc_array_single_inst_3 (
   .dest_out(smid_vdu1_dec0), // WIDTH-bit output: src_in synchronized to the destination clock domain. This
                        // output is registered.

   .dest_clk(m_axi_dec_aclk), // 1-bit input: Clock signal for the destination clock domain.
   .src_clk(s_axi_lite_aclk),   // 1-bit input: optional; required when SRC_INPUT_REG = 1
   .src_in(int_SMID_CONTROL_REGISTER_3)      // WIDTH-bit input: Input single-bit array to be synchronized to destination clock
                        // domain. It is assumed that each bit of the array is unrelated to the others. This
                        // is reflected in the constraints applied to this macro. To transfer a binary value
                        // losslessly across the two clock domains, use the XPM_CDC_GRAY macro instead.

);

xpm_cdc_array_single #(
   .DEST_SYNC_FF(2),   // DECIMAL; range: 2-10
   .INIT_SYNC_FF(0),   // DECIMAL; 0=disable simulation init values, 1=enable simulation init values
